def check(cell: tuple[int, int]) -> None:
    r, c = cell
    if not (0 <= r < rows and 0 <= c < cols):
        raise ValueError(f"cell {cell} is off the floor")
    if floor[r][c] != OPEN:
        raise ValueError(f"cell {cell} is not open")

